import math
from collections import Counter

def mi(xs, ys):
    n = len(xs)
    cx, cy, cxy = Counter(xs), Counter(ys), Counter(zip(xs, ys))
    return sum(c / n * math.log2(c * n / (cx[x] * cy[y])) for (x, y), c in cxy.items())

def rank_features(columns, labels):
    """Feature names by mutual information with labels, highest first; ties by name."""
    return sorted(columns, key=lambda name: (-mi(columns[name], labels), name))

